/**
 * Normalize file system path to POSIX import path
 * - Windows '\' → '/'
 * - Remove file extension
 */
export function normalizeImportPath(filePath: string): string {
    return filePath
        .replace(/\\/g, "/")                  // Windows → POSIX
        .replace(/\.[^/.]+$/, "");            // Remove extension
}

/**
 * Convert file path to route path
 * Examples:
 * - "src/pages/index.tsx"       → "/"
 * - "src/pages/home/[id].tsx"   → "/home/:id"
 * - "src/pages/[...slug].tsx"   → "/*"
 * - "src/pages/404.tsx"         → "*"
 */
export function toRoutePath(filePath: string, baseDir = ""): string {
    let path = normalizeImportPath(filePath);

    // Remove baseDir prefix if exists
    if (baseDir) {
        const normalizedBase = baseDir.replace(/\\/g, "/").replace(/\/$/, "");
        if (path.startsWith(normalizedBase)) {
            path = path.slice(normalizedBase.length);
        }
    }

    // Ensure leading slash
    if (!path.startsWith("/")) path = "/" + path;

    // Handle 404 / _404 pages as catch-all wildcard
    if (path === "/404" || path === "/_404") {
        return "*";
    }

    // Handle catch-all routes: [...slug] -> *
    path = path.replace(/\[\.\.\..+?\]/g, "*");

    // Handle dynamic parameters: [id] -> :id
    path = path.replace(/\[(.+?)\]/g, ":$1");

    // Convert index route: e.g. /home/index -> /home, /index -> /
    if (path.endsWith("/index")) {
        path = path.slice(0, -"/index".length) || "/";
    }

    // Remove trailing slash except for root "/"
    if (path.length > 1 && path.endsWith("/")) {
        path = path.slice(0, -1);
    }

    return path;
}
